//! The golden retrieval set, built from moderator duplicate judgements.
//!
//! Every pair here is a human decision: someone read two questions and ruled
//! that one is answered by the other. That is a relevance judgement produced by
//! a domain practitioner, for free, at a scale no hand-labelling budget would
//! reach -- and critically, not generated by the same class of model being
//! evaluated, which is the failure mode of synthetic eval sets.
//!
//! The duplicate question supplies the *query*; the canonical question it was
//! closed against is the *relevant document*.

use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};

/// One query with its known-relevant document.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct GoldenPair {
    /// Post id of the duplicate question. Also the query id.
    pub query_id: u64,
    /// The title, which is the closest thing in the corpus to what a user
    /// would actually type into a support search box.
    pub query_title: String,
    /// First part of the question body, for testing longer, messier queries.
    pub query_body: String,
    /// Post id of the canonical question. The document that must be retrieved.
    pub gold_doc_id: u64,
    pub gold_title: String,
    /// Tags of the gold document, for slicing results by topic.
    pub gold_tags: Vec<String>,
    /// Score of the gold question, as a graded-relevance signal.
    pub gold_score: i64,
}

/// A versioned eval set, pinned to the corpus it was built from.
///
/// The `corpus_hash` is what makes a historical eval number meaningful: a
/// recall figure against a different corpus is a different measurement, and
/// without the pin the two are indistinguishable in a results table.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GoldenSet {
    pub version: String,
    pub built_at: String,
    pub source: String,
    pub corpus_hash: String,
    pub pairs: Vec<GoldenPair>,
}

impl GoldenSet {
    pub fn load(path: impl AsRef<std::path::Path>) -> anyhow::Result<Self> {
        Ok(serde_json::from_str(&std::fs::read_to_string(path)?)?)
    }

    pub fn save(&self, path: impl AsRef<std::path::Path>) -> anyhow::Result<()> {
        std::fs::write(path, serde_json::to_string_pretty(self)?)?;
        Ok(())
    }

    pub fn len(&self) -> usize {
        self.pairs.len()
    }
    pub fn is_empty(&self) -> bool {
        self.pairs.is_empty()
    }

    /// Deterministic train/test split by query id.
    ///
    /// Hash-based rather than random so the split is stable across runs and
    /// machines without carrying a seed file. Tuning against the test half is
    /// how an eval set stops measuring anything.
    pub fn split(&self, test_fraction: f64) -> (Vec<&GoldenPair>, Vec<&GoldenPair>) {
        let cut = (test_fraction.clamp(0.0, 1.0) * u32::MAX as f64) as u32;
        let mut train = Vec::new();
        let mut test = Vec::new();
        for p in &self.pairs {
            let h = blake3::hash(&p.query_id.to_le_bytes());
            let v = u32::from_le_bytes(h.as_bytes()[..4].try_into().expect("4 bytes"));
            if v < cut { test.push(p) } else { train.push(p) }
        }
        (train, test)
    }

    /// Distribution of gold documents across tags, for slice reporting.
    pub fn tag_distribution(&self) -> HashMap<&str, usize> {
        let mut m: HashMap<&str, usize> = HashMap::new();
        for p in &self.pairs {
            for t in &p.gold_tags {
                *m.entry(t.as_str()).or_default() += 1;
            }
        }
        m
    }
}

/// Filters applied while building the set, each for a stated reason.
#[derive(Debug, Clone, Copy)]
pub struct BuildFilters {
    /// Drop pairs whose gold question scores below this. A gold document that
    /// the community rated negatively is a poor target to hold a retriever to.
    pub min_gold_score: i64,
    /// Require the query to have a title.
    pub require_title: bool,
    /// Drop queries shorter than this many characters; a three-word title is
    /// not a discriminating query and mostly measures noise.
    pub min_query_chars: usize,
}

impl Default for BuildFilters {
    fn default() -> Self {
        Self { min_gold_score: 1, require_title: true, min_query_chars: 20 }
    }
}

/// Statistics from a build, reported so the filtering is visible rather than
/// silent.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct BuildStats {
    pub duplicate_links: usize,
    pub resolved_both_posts: usize,
    pub dropped_missing_post: usize,
    pub dropped_low_score: usize,
    pub dropped_short_query: usize,
    pub dropped_no_title: usize,
    pub dropped_chained_duplicate: usize,
    pub kept: usize,
}

/// Assemble a golden set from duplicate links plus the posts they reference.
///
/// `posts` maps post id to (title, body, tags, score) for every id appearing in
/// a duplicate link. The caller collects those in a second streaming pass so
/// that neither the corpus nor the post map is ever fully materialised.
pub fn build(
    links: &[tz_ingest::DuplicateLink],
    posts: &HashMap<u64, (String, String, Vec<String>, i64)>,
    filters: BuildFilters,
) -> (Vec<GoldenPair>, BuildStats) {
    let mut stats = BuildStats { duplicate_links: links.len(), ..Default::default() };

    // A question closed as a duplicate is itself a poor retrieval target: it
    // was removed from circulation. Excluding gold documents that are
    // themselves duplicates keeps the target set canonical.
    let known_duplicates: HashSet<u64> = links.iter().map(|l| l.post_id).collect();

    let mut out = Vec::new();
    for l in links {
        let (Some(q), Some(g)) = (posts.get(&l.post_id), posts.get(&l.related_post_id)) else {
            stats.dropped_missing_post += 1;
            continue;
        };
        stats.resolved_both_posts += 1;

        if known_duplicates.contains(&l.related_post_id) {
            stats.dropped_chained_duplicate += 1;
            continue;
        }
        if filters.require_title && (q.0.is_empty() || g.0.is_empty()) {
            stats.dropped_no_title += 1;
            continue;
        }
        if g.3 < filters.min_gold_score {
            stats.dropped_low_score += 1;
            continue;
        }
        if q.0.len() < filters.min_query_chars {
            stats.dropped_short_query += 1;
            continue;
        }

        let body: String = q.1.chars().take(500).collect();
        out.push(GoldenPair {
            query_id: l.post_id,
            query_title: q.0.clone(),
            query_body: body,
            gold_doc_id: l.related_post_id,
            gold_title: g.0.clone(),
            gold_tags: g.2.clone(),
            gold_score: g.3,
        });
    }

    // A question can be closed against several canonical targets. Keep the
    // first per query so that recall@k is not inflated by a query having
    // several chances to hit.
    let mut seen = HashSet::new();
    out.retain(|p| seen.insert(p.query_id));

    stats.kept = out.len();
    (out, stats)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tz_ingest::DuplicateLink;

    fn posts() -> HashMap<u64, (String, String, Vec<String>, i64)> {
        HashMap::from([
            (1, ("How do I configure nginx upstream timeouts".into(), "body one".into(), vec!["nginx".into()], 10)),
            (2, ("Canonical nginx timeout question here".into(), "body two".into(), vec!["nginx".into()], 25)),
            (3, ("Short".into(), "b".into(), vec![], 5)),
            (4, ("A negatively scored canonical question".into(), "b".into(), vec![], -2)),
            (5, ("Another perfectly fine long question title".into(), "b".into(), vec![], 3)),
        ])
    }

    #[test]
    fn a_clean_pair_is_kept() {
        let links = [DuplicateLink { post_id: 1, related_post_id: 2 }];
        let (pairs, stats) = build(&links, &posts(), BuildFilters::default());
        assert_eq!(pairs.len(), 1);
        assert_eq!(stats.kept, 1);
        assert_eq!(pairs[0].query_id, 1);
        assert_eq!(pairs[0].gold_doc_id, 2);
        assert_eq!(pairs[0].gold_score, 25);
    }

    #[test]
    fn pairs_referencing_absent_posts_are_dropped() {
        let links = [DuplicateLink { post_id: 1, related_post_id: 999 }];
        let (pairs, stats) = build(&links, &posts(), BuildFilters::default());
        assert!(pairs.is_empty());
        assert_eq!(stats.dropped_missing_post, 1);
    }

    #[test]
    fn a_negatively_scored_gold_document_is_not_a_fair_target() {
        let links = [DuplicateLink { post_id: 1, related_post_id: 4 }];
        let (pairs, stats) = build(&links, &posts(), BuildFilters::default());
        assert!(pairs.is_empty());
        assert_eq!(stats.dropped_low_score, 1);
    }

    #[test]
    fn very_short_queries_are_excluded_as_non_discriminating() {
        let links = [DuplicateLink { post_id: 3, related_post_id: 2 }];
        let (pairs, stats) = build(&links, &posts(), BuildFilters::default());
        assert!(pairs.is_empty());
        assert_eq!(stats.dropped_short_query, 1);
    }

    #[test]
    fn a_gold_document_that_is_itself_a_duplicate_is_excluded() {
        // 1 -> 2 and 5 -> 1. Post 1 is a duplicate, so it is not canonical and
        // should not serve as a gold target for query 5.
        let links = [
            DuplicateLink { post_id: 1, related_post_id: 2 },
            DuplicateLink { post_id: 5, related_post_id: 1 },
        ];
        let (pairs, stats) = build(&links, &posts(), BuildFilters::default());
        assert_eq!(pairs.len(), 1);
        assert_eq!(pairs[0].query_id, 1);
        assert_eq!(stats.dropped_chained_duplicate, 1);
    }

    #[test]
    fn a_query_closed_against_two_targets_counts_once() {
        // Otherwise that query gets two chances to be hit and recall inflates.
        let links = [
            DuplicateLink { post_id: 1, related_post_id: 2 },
            DuplicateLink { post_id: 1, related_post_id: 5 },
        ];
        let (pairs, _) = build(&links, &posts(), BuildFilters::default());
        assert_eq!(pairs.len(), 1);
    }

    #[test]
    fn the_split_is_deterministic_and_disjoint() {
        let gs = GoldenSet {
            version: "t".into(),
            built_at: "t".into(),
            source: "t".into(),
            corpus_hash: "t".into(),
            pairs: (0..1000)
                .map(|i| GoldenPair {
                    query_id: i,
                    query_title: format!("q{i}"),
                    query_body: String::new(),
                    gold_doc_id: i + 10_000,
                    gold_title: String::new(),
                    gold_tags: vec![],
                    gold_score: 1,
                })
                .collect(),
        };
        let (tr1, te1) = gs.split(0.2);
        let (tr2, te2) = gs.split(0.2);
        assert_eq!(tr1.len(), tr2.len());
        assert_eq!(te1.len(), te2.len());
        assert_eq!(tr1.len() + te1.len(), 1000);
        // Roughly the requested fraction, and never overlapping.
        assert!((te1.len() as f64 / 1000.0 - 0.2).abs() < 0.05, "got {}", te1.len());
        let test_ids: HashSet<u64> = te1.iter().map(|p| p.query_id).collect();
        assert!(tr1.iter().all(|p| !test_ids.contains(&p.query_id)));
    }
}
